def findCircleNum(isConnected: list[list[int]]) -> int:
    n = len(isConnected)
    visited = [False] * n
    provinces = 0
    def dfs(u):
        visited[u] = True
        for v in range(n):
            if isConnected[u][v] == 1 and not visited[v]:
                dfs(v)
    for i in range(n):
        if not visited[i]:
            provinces += 1
            dfs(i)
    return provinces

